files=subprocess.check_output(['git','diff','--name-only','--','.skilled/skills/sk-code/sk-code-skilled'],text=True).split()
for f in files:
    if not f.endswith('.md'): continue
    lines=open(f).read().splitlines()
    # find H1
    h1=[i for i,l in enumerate(lines) if re.match(r'^# ',l)]
    h2=[(i,l) for i,l in enumerate(lines) if re.match(r'^## ',l)]
    nums=[]
    for i,l in h2:
        m=re.match(r'^## (\d+)\. ',l)
        nums.append(int(m.group(1)) if m else None)
    issues=[]
    if any(n is None for n in nums): issues.append('unnumbered H2')
    if nums and [n for n in nums if n is not None]!=list(range(1,len([n for n in nums if n is not None])+1)):
        issues.append('H2 numbers '+str(nums))
    rel=[i for i,(j,l) in enumerate(h2) if 'RELATED' in l.upper()]
    if rel and rel[-1]!=len(h2)-1: issues.append('related not last: '+h2[rel[-1]][1])
    # intro
    intro=''
    if h1:
        k=h1[0]+1
        while k<len(lines) and not lines[k].strip(): k+=1
        if k<len(lines) and not lines[k].startswith('#'):
            intro=lines[k].strip()
    if re.search(r'^(This document describes|The sections below|This reference explains|The examples below)', intro):
        issues.append('pointer intro: '+intro[:80])
    # overview purpose/when
    oi=[i for i,l in enumerate(lines) if re.match(r'^## 1\. OVERVIEW',l)]
    if oi:
        seg='\n'.join(lines[oi[0]:h2[1][0] if len(h2)>1 else len(lines)])
        if '### Purpose' not in seg and '### What It Does' not in seg: issues.append('no Purpose in overview')
        if '### When to Use' not in seg and '### When To Use' not in seg and '### What It Does' not in seg: issues.append('no When to Use in overview')
    if issues: print(f, '|', '; '.join(issues))
EOF

